css='''*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;background:#f8f6f0;color:#30463d;font:16px/1.75 system-ui,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif}a{color:#345f49;text-underline-offset:4px}a:hover{color:#183e29}button,input{font:inherit}a:focus-visible,button:focus-visible,input:focus-visible{outline:3px solid #a57945;outline-offset:4px}header{border-bottom:1px solid #dfE4d9;background:#fffdf8}header .bar{max-width:1120px;margin:auto;padding:19px 28px;display:flex;align-items:center;justify-content:space-between;gap:18px}.brand{display:flex;align-items:center;gap:12px;text-decoration:none;color:inherit}.brand img{width:48px;height:48px;border-radius:16px}.brand strong{display:block;font-size:18px;line-height:1.2;letter-spacing:-.5px}.brand small{display:block;font-size:10px;letter-spacing:2px;text-transform:uppercase;margin-top:5px;color:#697b6d}.lang{font-size:13px;display:flex;gap:8px;align-items:center}.lang a{padding:6px 9px;border-radius:8px}.lang a[aria-current]{background:#e5eddf;font-weight:700;text-decoration:none}nav{max-width:1120px;margin:0 auto;padding:0 28px 14px;display:flex;flex-wrap:wrap;gap:8px 24px;font-size:13px}nav a{text-decoration:none}nav a[aria-current]{font-weight:750;text-decoration:underline}main{max-width:1064px;margin:0 auto;padding:56px 28px 70px}.eyebrow{font-size:11px;font-weight:700;letter-spacing:2px;text-transform:uppercase;color:#677e64}.hero{max-width:770px;margin-bottom:42px}h1{font-size:clamp(34px,5vw,54px);font-weight:650;line-height:1.14;letter-spacing:-2px;margin:16px 0 20px}h2{font-size:23px;letter-spacing:-.6px;line-height:1.35;margin:36px 0 12px}h3{font-size:17px;line-height:1.4;margin:20px 0 8px}p{margin:0 0 17px}.lead{font-size:19px;line-height:1.65;color:#637366}.meta{font-size:12px;color:#6d796f}.hub{display:grid;grid-template-columns:repeat(3,1fr);gap:17px}.hub a{display:flex;flex-direction:column;padding:27px 24px;min-height:260px;background:#fffdf9;border:1px solid #dfe4d9;border-radius:24px;text-decoration:none;transition:transform .2s}.hub a:hover{transform:translateY(-3px)}.hub a:nth-child(2){background:#ecf0e5}.hub a:nth-child(3){background:#f7e9df}.number{font-size:12px;font-weight:700;letter-spacing:2px;color:#7d8b76}.hub h2{margin:30px 0 10px;font-size:25px}.hub p{font-size:14px;color:#677569}.hub .arrow{margin-top:auto;font-size:22px}.note{border:1px solid #d8e2d0;background:#edf2e7;padding:20px 24px;border-radius:18px;margin:26px 0}.note p:last-child{margin:0}.note.warn{background:#fbede5;border-color:#eddbce}.layout{display:grid;grid-template-columns:210px minmax(0,1fr);gap:50px}.toc{align-self:start;position:sticky;top:24px;border-top:1px solid #cfd8c8;padding-top:16px;font-size:13px}.toc strong{display:block;margin-bottom:10px}.toc a{display:block;margin-bottom:9px;text-decoration:none}.article{min-width:0;max-width:740px}.article h2:first-child{margin-top:0}.article section{scroll-margin-top:24px}.article ul,.article ol{padding-left:23px;margin:12px 0 23px}.article li{margin:8px 0}.tablewrap{overflow-x:auto;margin:20px 0}table{width:100%;border-collapse:collapse;font-size:14px;text-align:left}th{background:#e8eee0;font-weight:650}th,td{padding:13px 15px;border-bottom:1px solid #dce3d6;vertical-align:top}th:first-child{width:33%}.card{background:#fffdf9;border:1px solid #dfe4d9;border-radius:22px;padding:25px 27px;margin:22px 0}.card h2:first-child{margin-top:0}.step{display:inline-flex;background:#e6eddf;color:#4d6d51;border-radius:50%;width:32px;height:32px;align-items:center;justify-content:center;font-weight:700;margin-right:9px}.btn{display:inline-flex;align-items:center;justify-content:center;gap:9px;border:0;border-radius:12px;background:#4b6d56;color:white;padding:12px 18px;text-decoration:none;font-size:14px;font-weight:650;cursor:pointer}.btn:hover{background:#33553e;color:white}.btn.secondary{background:#e9ede3;color:#385640;border:1px solid #d4ddcc}label{display:block;font-size:14px;font-weight:650;margin:20px 0 7px}input{width:100%;border:1px solid #bccbb6;background:white;border-radius:11px;padding:12px 14px;color:#30463d;margin-bottom:15px}.small{font-size:13px;color:#647064}.contact{font-size:clamp(16px,3vw,23px);font-weight:650;overflow-wrap:anywhere}.actions{display:flex;flex-wrap:wrap;align-items:center;gap:12px;margin:20px 0}.status{font-size:13px;min-height:24px}footer{border-top:1px solid #dfe4d9;padding:30px 28px 38px;font-size:12px;color:#677569}footer>div{max-width:1008px;margin:auto;display:flex;justify-content:space-between;gap:24px;flex-wrap:wrap}.skip{position:absolute;left:20px;top:-100px;background:white;padding:10px}.skip:focus{top:10px}.sectionline{height:1px;background:#dfe4d9;margin:45px 0}.links{display:flex;flex-wrap:wrap;gap:18px;font-size:13px}@media(max-width:760px){header .bar{padding:16px 20px}.brand img{width:42px;height:42px}.brand strong{font-size:16px}.brand small{font-size:9px;letter-spacing:1.5px}.lang{font-size:12px;gap:0}nav{padding:0 20px 14px;gap:8px 18px}main{padding:35px 20px 48px}h1{letter-spacing:-1.3px}.lead{font-size:17px}.hub{grid-template-columns:1fr}.hub a{min-height:205px}.hub h2{margin-top:20px}.layout{display:block}.toc{position:static;margin-bottom:30px;display:flex;gap:6px 16px;flex-wrap:wrap}.toc strong{width:100%}.toc a{margin:0}.card{padding:22px 20px}.contact{font-size:18px}footer{padding:25px 20px}th,td{padding:11px}}@media(prefers-reduced-motion:reduce){html{scroll-behavior:auto}.hub a{transition:none}}'''
(D/'assets/site.css').write_text(css)
nav_en=[('','Help home'),('privacy/','Privacy policy'),('account-deletion/','Delete your account'),('support/','Contact support'),('terms/','Terms & community rules')]
nav_vi=[('','Trang hỗ trợ'),('privacy/','Quyền riêng tư'),('account-deletion/','Xóa tài khoản'),('support/','Liên hệ hỗ trợ'),('terms/','Điều khoản & nội quy')]

def shell(lang,key,title,lead,body,toc=None):
 vi=lang=='vi';base=P+('/vi/' if vi else '/');other=P+('/' if vi else '/vi/');routes=nav_vi if vi else nav_en
 nav=''.join(f'<a href="{base+r}"'+(' aria-current="page"' if r==key else '')+f'>{label}</a>' for r,label in routes)
 langs=f'<div class="lang" aria-label="Language"><a href="{P}/{key}" lang="en"'+(' aria-current="true"' if not vi else '')+f'>English</a><span aria-hidden="true">/</span><a href="{P}/vi/{key}" lang="vi"'+(' aria-current="true"' if vi else '')+'>Tiếng Việt</a></div>'
 side=('Mục lục' if vi else 'On this page')
 content=f'<div class="layout"><aside class="toc"><strong>{side}</strong>'+''.join(f'<a href="#{id}">{txt}</a>' for id,txt in toc)+f'</aside><article class="article">{body}</article></div>' if toc else body
 fulltitle=html.escape(title.replace('<br>',' ')+' · Little Days')
 document=f'''<!doctype html><html lang="{lang}"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="description" content="{html.escape(lead,quote=True)}"><meta name="theme-color" content="#f8f6f0"><title>{fulltitle}</title><link rel="icon" href="{P}/assets/baby-logo.webp"><link rel="stylesheet" href="{P}/assets/site.css"></head><body><a class="skip" href="#main">{'Đến nội dung chính' if vi else 'Skip to content'}</a><header><div class="bar"><a class="brand" href="{base}"><img src="{P}/assets/baby-logo.webp" width="48" height="48" alt="Little Days"><span><strong>Little Days</strong><small>{'Quyền riêng tư & hỗ trợ' if vi else 'Privacy & support'}</small></span></a>{langs}</div><nav aria-label="{'Điều hướng chính' if vi else 'Main navigation'}">{nav}</nav></header><main id="main"><div class="hero"><div class="eyebrow">LITTLE DAYS · RUBEZAPPS</div><h1>{title}</h1><p class="lead">{lead}</p><p class="meta">{'Cập nhật ngày 23 tháng 10 năm 2026' if vi else 'Updated 23 October 2026'}</p></div>{content}</main><footer><div><span>Little Days · RubezApps<br>{'Điều hành bởi Vũ Trần Nhật Nguyên' if vi else 'Operated by Vũ Trần Nhật Nguyên'}</span><span><a href="mailto:appmakernguyen@gmail.com">appmakernguyen@gmail.com</a><br>{'Dành cho cha mẹ và người chăm sóc trưởng thành.' if vi else 'For adult parents and caregivers.'}</span></div></footer><script src="{P}/assets/site.js" defer></script></body></html>'''
 path=D/('vi' if vi else '')/key;path.mkdir(parents=True,exist_ok=True);(path/'index.html').write_text(document)

privacy_en='''<section id="about"><h2>About this policy</h2><p>Little Days is a parent community and baby journal app for adult parents and caregivers, operated by Vũ Trần Nhật Nguyên under the RubezApps developer name. She is the privacy and support contact at <a href="mailto:appmakernguyen@gmail.com">appmakernguyen@gmail.com</a>. This policy covers the Little Days app and this public support website.</p><p>You choose what to record about a child. Only provide information you have authority to use, and obtain any permissions needed before uploading someone else’s photo, video or personal information.</p></section>
<section id="data"><h2>Information we handle</h2><div class="tablewrap"><table><thead><tr><th>Information</th><th>What it is used for</th></tr></thead><tbody><tr><td>Account details</td><td>Email address, account identifier and authentication information for sign-in, email verification, password recovery and account administration. Authentication is handled by Supabase.</td></tr><tr><td>Baby journal</td><td>Details you enter, such as baby’s name, date of birth, photo, optional weight, height and head circumference, bottle amounts, breastfeeding duration, food, diaper and sleep records, timestamps and caregiver attribution. These provide your journal, timers and summaries.</td></tr><tr><td>Family and profile details</td><td>Your chosen display name, photo, family role, family membership, invitations and access permissions. These identify caregivers and control who can view or edit shared records.</td></tr><tr><td>Community content</td><td>Photos, short videos, text posts, likes and comments you choose to publish, together with author details and timestamps.</td></tr><tr><td>Preferences and notifications</td><td>Language, measurement units, local settings, reminder schedules, notification preferences, device identifiers or credentials used to deliver app features, and activity notifications about your posts.</td></tr><tr><td>Plans, rewards and safety</td><td>Plan status, entitlement dates, posting counts, ad reward verification, upload usage, community-rule acceptance, reports, blocks, moderation actions and support messages. These provide features, enforce limits and prevent abuse.</td></tr><tr><td>Technical information</td><td>Service providers process network requests, IP addresses, device or app information and operational logs to deliver, secure and troubleshoot their services. Google’s advertising SDK has the additional practices described below.</td></tr></tbody></table></div><p>Local drafts, preferences and cached content may be stored on your device. A family’s shared profile and journal are stored on our backend. Content you publish is uploaded to the community service.</p></section>
<section id="sharing"><h2>Private journal, shared community</h2><div class="note"><p><strong>Your family journal and community posts have different audiences.</strong> Community posts are visible to other signed-in app users, not just invited family members.</p></div><ul><li>Shared baby profiles and journal records are available to family members according to the permissions managed by the family owner.</li><li>Your community display name, role, profile photo, posts, photos, videos, likes and comments can be shown to other signed-in app users.</li><li>Authorized operators can access service data when needed for support, security, moderation or maintenance. The moderation interface does not display private baby journal records.</li><li>People who receive content may save, photograph or download it. We cannot remotely remove copies they keep.</li></ul><p>We use the information above to operate the app, synchronize families, display posts, deliver reminders, enforce account permissions and plan rules, prevent fraud and respond to requests. We do not provide private baby journal records, growth measurements or family profile photos to Google for advertising targeting.</p></section>
<section id="providers"><h2>Providers, storage and advertising</h2><p><strong>Supabase</strong> provides authentication, database, file storage and backend functions. The app’s project is hosted in Singapore; provider support and infrastructure operations may involve processing in other countries. See <a href="https://supabase.com/privacy" rel="noopener noreferrer">Supabase’s privacy policy</a>.</p><p><strong>Google AdMob / Google Mobile Ads SDK</strong> is integrated in the Android app for advertising, including optional rewarded ads. When the SDK operates, it may collect and share IP addresses (which can indicate approximate location), ad and app interactions, diagnostics, and device/account identifiers such as the advertising ID, for advertising, measurement and fraud prevention. Availability and personalization depend on consent, SDK settings and applicable rules. See <a href="https://policies.google.com/privacy" rel="noopener noreferrer">Google’s privacy policy</a> and <a href="https://policies.google.com/technologies/ads" rel="noopener noreferrer">Google’s advertising information</a>. Where available, use the app’s advertising privacy controls and Android’s advertising settings.</p><p><strong>Email and support:</strong> Google/Gmail is used for our support mailbox and may process account-service emails sent through the configured email service. Your email address and message are processed when you contact us.</p><p><strong>Other services:</strong> ExchangeRate-API supplies currency estimates through our server without receiving baby journal records. This public help website is hosted through OpenAI Sites on Cloudflare infrastructure; network and security information may be processed to serve it.</p><p>We store account plan and reward-verification information. Purchases are not connected in the current test build. If Google Play subscriptions become available, Google Play will process payments and its terms will be shown before purchase; we do not receive or store your payment-card details.</p></section>
<section id="permissions"><h2>Your choices and device permissions</h2><p>You choose whether to add media, invite a caregiver or publish a community post. Recording media uses a compatible camera app or the device picker. Camera, microphone, selected-media and notification access depend on your Android version and the feature you use; you can manage permissions in Android Settings. Denying optional access can prevent that feature from working.</p><p>Notifications may include information about sleep, feeding or community activity on your lock screen. You can turn off notifications or hide sensitive notification content in Android Settings. Disable a reminder in the app if you no longer want it.</p><p>The app’s caregiver-entered journal is not a medical device, diagnosis, treatment or emergency service. Consult a qualified healthcare professional for medical questions.</p></section>
<section id="retention"><h2>Retention and account deletion</h2><p>Active account, family and community records are kept to provide the service until removed through the app or an account-deletion request. Deleting an individual post removes that post and its associated uploaded media and comments from active app storage. “Clear day” only removes the selected day’s journal entries; it does not delete your account.</p><p>Account deletion removes your app sign-in account and associated active app records, including your community profile, posts, comments, likes, uploaded community media, notification/device records, plan and ad-reward records, app support records and related reports or blocks. If you own a family, its shared baby profile, journal, memberships and invitations are also removed for everyone. Other members’ separate sign-in accounts are not deleted. If you are an invited member, your membership and journal entries you authored are removed; other family members’ records remain.</p><p>Deletion from active app storage does not remotely erase files saved by others, cached copies on other devices, provider-controlled operational/security logs, or independent Google payment/advertising records. Providers handle their records and any recovery copies under their own retention policies. Support emails can remain in our mailbox while needed to verify and fulfil a request or address a dispute; you may ask us to remove the correspondence when it is no longer needed. Any retention required by law or necessary for an active security/legal matter is limited to that purpose.</p><p>See <a href="/little-days/account-deletion/">Delete your account</a> for the in-app route, email request method and what deletion affects. Uninstalling the app alone does not delete cloud records. Deletion does not cancel a Google Play subscription; manage subscriptions separately in Google Play.</p></section>
<section id="rights"><h2>Security, requests and children’s information</h2><p>Connections to our services use HTTPS. Server-side checks and restricted storage help protect shared records. No system is completely secure; keep a separate copy of information you cannot afford to lose.</p><p>The app is intended for adults, not for children to create accounts or participate in the community. Baby information is provided by their authorized parents or caregivers. Contact us if information was uploaded without permission or a child created an account.</p><p>You can update information through the app and contact us to request access, correction, deletion, or help exercising privacy rights that apply where you live. We may need to verify account ownership, normally by correspondence with the account email. Do not send your password, verification codes or identity documents unless we separately explain a necessary, secure verification process.</p><p>We may update this policy when features, providers or data practices change. The current policy is available at this URL with its update date.</p></section>'''
privacy_vi='''<section id="about"><h2>Về chính sách này</h2><p>Little Days là ứng dụng cộng đồng cha mẹ và nhật ký chăm sóc bé dành cho cha mẹ, người chăm sóc trưởng thành, do Vũ Trần Nhật Nguyên điều hành dưới tên nhà phát triển RubezApps, đồng thời là đầu mối về quyền riêng tư và hỗ trợ tại <a href="mailto:appmakernguyen@gmail.com">appmakernguyen@gmail.com</a>. Chính sách áp dụng cho ứng dụng Little Days và trang hỗ trợ công khai này.</p><p>Bạn quyết định thông tin nào về trẻ sẽ được ghi lại. Chỉ cung cấp thông tin mà bạn có quyền sử dụng và có sự cho phép cần thiết trước khi đăng ảnh, video hoặc thông tin cá nhân của người khác.</p></section>
<section id="data"><h2>Thông tin được xử lý</h2><div class="tablewrap"><table><thead><tr><th>Thông tin</th><th>Mục đích sử dụng</th></tr></thead><tbody><tr><td>Tài khoản</td><td>Địa chỉ email, mã tài khoản và thông tin xác thực để đăng nhập, xác minh email, khôi phục mật khẩu và quản lý tài khoản. Supabase xử lý việc xác thực.</td></tr><tr><td>Nhật ký của bé</td><td>Thông tin bạn nhập như tên, ngày sinh, ảnh, cân nặng, chiều cao, vòng đầu tùy chọn, lượng sữa bình, thời gian bú mẹ, thức ăn, thay tã, giấc ngủ, thời điểm ghi và người chăm sóc đã ghi. Dữ liệu phục vụ nhật ký, bộ đếm giờ và thống kê.</td></tr><tr><td>Hồ sơ và gia đình</td><td>Tên hiển thị, ảnh, vai trò trong gia đình, thành viên, lời mời và quyền truy cập để nhận diện người chăm sóc và quản lý quyền xem, chỉnh sửa.</td></tr><tr><td>Nội dung cộng đồng</td><td>Ảnh, video ngắn, bài viết, lượt thích và bình luận bạn đăng, cùng thông tin người đăng và thời gian.</td></tr><tr><td>Cài đặt và thông báo</td><td>Ngôn ngữ, đơn vị đo, tùy chọn trên thiết bị, lịch nhắc, cài đặt thông báo, mã thiết bị hoặc thông tin xác thực cho các tính năng và thông báo tương tác với bài của bạn.</td></tr><tr><td>Gói sử dụng, phần thưởng, an toàn</td><td>Trạng thái gói, thời hạn quyền lợi, số bài đăng, xác minh thưởng quảng cáo, dung lượng tải lên, chấp nhận nội quy, báo cáo, chặn tài khoản, xử lý kiểm duyệt và tin nhắn hỗ trợ. Dữ liệu giúp vận hành tính năng, giới hạn và ngăn lạm dụng.</td></tr><tr><td>Thông tin kỹ thuật</td><td>Nhà cung cấp xử lý yêu cầu mạng, địa chỉ IP, thông tin thiết bị hoặc ứng dụng và nhật ký vận hành để cung cấp, bảo vệ và khắc phục sự cố dịch vụ. SDK quảng cáo của Google có các hoạt động bổ sung bên dưới.</td></tr></tbody></table></div><p>Bản nháp, tùy chọn và nội dung lưu đệm có thể nằm trên thiết bị. Hồ sơ, nhật ký gia đình dùng chung được lưu trên hệ thống máy chủ. Nội dung bạn đăng được tải lên dịch vụ cộng đồng.</p></section>
<section id="sharing"><h2>Nhật ký riêng, cộng đồng chung</h2><div class="note"><p><strong>Nhật ký gia đình và bài đăng cộng đồng có đối tượng xem khác nhau.</strong> Bài đăng cộng đồng hiển thị cho người dùng ứng dụng đã đăng nhập, không chỉ các thành viên gia đình được mời.</p></div><ul><li>Hồ sơ và nhật ký dùng chung hiển thị cho thành viên gia đình theo quyền do chủ gia đình quản lý.</li><li>Tên hiển thị, vai trò, ảnh hồ sơ, bài viết, ảnh, video, lượt thích và bình luận có thể hiển thị cho người dùng đã đăng nhập khác.</li><li>Người vận hành được ủy quyền có thể truy cập dữ liệu khi cần để hỗ trợ, bảo mật, kiểm duyệt hoặc bảo trì. Giao diện kiểm duyệt không hiển thị nhật ký riêng của bé.</li><li>Người nhận có thể lưu, chụp lại hoặc tải nội dung xuống. Chúng tôi không thể xóa từ xa những bản sao họ giữ.</li></ul><p>Chúng tôi dùng thông tin để vận hành ứng dụng, đồng bộ gia đình, hiển thị bài viết, gửi lời nhắc, quản lý quyền và gói, ngăn gian lận và phản hồi yêu cầu. Chúng tôi không cung cấp nhật ký riêng của bé, số đo tăng trưởng hoặc ảnh hồ sơ gia đình cho Google để nhắm mục tiêu quảng cáo.</p></section>
<section id="providers"><h2>Nhà cung cấp, lưu trữ và quảng cáo</h2><p><strong>Supabase</strong> cung cấp xác thực, cơ sở dữ liệu, lưu tệp và các chức năng máy chủ. Dự án ứng dụng được lưu trữ tại Singapore; hoạt động hỗ trợ, hạ tầng của nhà cung cấp có thể liên quan đến xử lý ở các quốc gia khác. Xem <a href="https://supabase.com/privacy" rel="noopener noreferrer">chính sách của Supabase</a>.</p><p><strong>Google AdMob / Google Mobile Ads SDK</strong> được tích hợp trong ứng dụng Android để cung cấp quảng cáo, gồm quảng cáo nhận thưởng tùy chọn. Khi hoạt động, SDK có thể thu thập và chia sẻ địa chỉ IP (có thể cho biết vị trí gần đúng), tương tác quảng cáo hoặc ứng dụng, thông tin chẩn đoán và mã thiết bị/tài khoản như mã quảng cáo, phục vụ quảng cáo, đo lường và chống gian lận. Quảng cáo và cá nhân hóa tùy thuộc sự đồng ý, cài đặt SDK và quy định áp dụng. Xem <a href="https://policies.google.com/privacy" rel="noopener noreferrer">chính sách Google</a> và <a href="https://policies.google.com/technologies/ads" rel="noopener noreferrer">thông tin quảng cáo của Google</a>. Nếu có, dùng tùy chọn quyền riêng tư quảng cáo trong ứng dụng và cài đặt quảng cáo Android.</p><p><strong>Email và hỗ trợ:</strong> Google/Gmail cung cấp hộp thư hỗ trợ và có thể xử lý email dịch vụ tài khoản qua dịch vụ email được cấu hình. Khi bạn liên hệ, địa chỉ email và nội dung thư được xử lý.</p><p><strong>Dịch vụ khác:</strong> ExchangeRate-API cung cấp tỷ giá ước tính qua máy chủ mà không nhận nhật ký của bé. Trang trợ giúp công khai này dùng OpenAI Sites trên hạ tầng Cloudflare; dữ liệu mạng và bảo mật có thể được xử lý để cung cấp trang.</p><p>Chúng tôi lưu thông tin gói và xác minh thưởng. Bản thử nghiệm hiện tại chưa kết nối mua hàng. Nếu đăng ký Google Play được cung cấp, Google Play xử lý thanh toán và điều khoản sẽ hiển thị trước khi mua; chúng tôi không nhận hay lưu thông tin thẻ thanh toán của bạn.</p></section>
<section id="permissions"><h2>Lựa chọn và quyền trên thiết bị</h2><p>Bạn lựa chọn thêm nội dung đa phương tiện, mời người chăm sóc hoặc đăng bài. Việc ghi hình dùng ứng dụng camera tương thích hoặc bộ chọn trên thiết bị. Quyền camera, micrô, nội dung được chọn và thông báo phụ thuộc phiên bản Android, tính năng bạn sử dụng; bạn có thể quản lý trong Cài đặt Android. Từ chối quyền tùy chọn có thể khiến tính năng tương ứng không hoạt động.</p><p>Thông báo có thể hiển thị thông tin giấc ngủ, ăn uống hoặc cộng đồng trên màn hình khóa. Bạn có thể tắt thông báo hoặc ẩn nội dung nhạy cảm trong Cài đặt Android. Tắt lời nhắc trong ứng dụng nếu không còn muốn nhận.</p><p>Nhật ký do người chăm sóc nhập không phải thiết bị y tế, công cụ chẩn đoán, điều trị hay dịch vụ cấp cứu. Hãy tham khảo chuyên gia y tế cho vấn đề sức khỏe.</p></section>
<section id="retention"><h2>Lưu giữ và xóa tài khoản</h2><p>Dữ liệu tài khoản, gia đình và cộng đồng đang hoạt động được giữ để cung cấp dịch vụ cho đến khi được xóa trong ứng dụng hoặc theo yêu cầu xóa tài khoản. Xóa một bài sẽ xóa bài, nội dung đã tải lên và bình luận liên quan khỏi dữ liệu đang hoạt động. “Clear day” chỉ xóa nhật ký ngày được chọn, không xóa tài khoản.</p><p>Xóa tài khoản sẽ xóa tài khoản đăng nhập và dữ liệu ứng dụng đang hoạt động liên quan, gồm hồ sơ cộng đồng, bài viết, bình luận, lượt thích, nội dung cộng đồng đã tải lên, dữ liệu thông báo/thiết bị, gói và thưởng quảng cáo, tin hỗ trợ trong ứng dụng, báo cáo hoặc chặn liên quan. Nếu bạn là chủ gia đình, hồ sơ bé, nhật ký chung, thành viên và lời mời của gia đình cũng bị xóa cho mọi người. Tài khoản đăng nhập riêng của thành viên khác không bị xóa. Nếu bạn là thành viên được mời, tư cách thành viên và nhật ký do bạn tạo bị xóa; dữ liệu khác của gia đình vẫn giữ.</p><p>Xóa khỏi dữ liệu đang hoạt động không xóa từ xa tệp người khác đã lưu, bản lưu đệm trên thiết bị khác, nhật ký vận hành/bảo mật do nhà cung cấp kiểm soát hoặc hồ sơ thanh toán/quảng cáo độc lập của Google. Nhà cung cấp xử lý hồ sơ và bản khôi phục theo chính sách lưu giữ riêng. Email hỗ trợ có thể được giữ khi cần xác minh, hoàn tất yêu cầu hoặc giải quyết tranh chấp; bạn có thể yêu cầu xóa thư khi không còn cần thiết. Việc giữ lại theo luật hoặc cho vấn đề bảo mật/pháp lý đang xử lý chỉ giới hạn trong mục đích đó.</p><p>Xem <a href="/little-days/vi/account-deletion/">Xóa tài khoản</a> để biết cách xóa trong ứng dụng, gửi yêu cầu bằng email và phạm vi ảnh hưởng. Chỉ gỡ ứng dụng không xóa dữ liệu đám mây. Xóa tài khoản không hủy đăng ký Google Play; hãy quản lý riêng trong Google Play.</p></section>
<section id="rights"><h2>Bảo mật, yêu cầu và thông tin trẻ em</h2><p>Dịch vụ dùng HTTPS. Kiểm tra quyền trên máy chủ và lưu trữ có hạn chế giúp bảo vệ dữ liệu dùng chung. Không hệ thống nào bảo mật tuyệt đối; hãy giữ bản sao riêng của thông tin quan trọng.</p><p>Ứng dụng dành cho người trưởng thành, không dành cho trẻ tạo tài khoản hoặc tham gia cộng đồng. Thông tin của bé do cha mẹ hoặc người chăm sóc có thẩm quyền cung cấp. Liên hệ nếu thông tin bị đăng khi chưa có phép hoặc trẻ đã tạo tài khoản.</p><p>Bạn có thể cập nhật dữ liệu trong ứng dụng, liên hệ yêu cầu truy cập, sửa, xóa hoặc hỗ trợ thực hiện quyền riêng tư áp dụng tại nơi bạn sống. Chúng tôi có thể cần xác minh chủ tài khoản, thường qua địa chỉ email của tài khoản. Không gửi mật khẩu, mã xác minh hoặc giấy tờ tùy thân trừ khi chúng tôi giải thích riêng một quy trình xác minh an toàn và cần thiết.</p><p>Chính sách có thể thay đổi khi tính năng, nhà cung cấp hoặc cách xử lý dữ liệu thay đổi. Phiên bản hiện hành tại địa chỉ này có ghi ngày cập nhật.</p></section>'''

def deletion(vi=False):
 if not vi:return '''<section id="in-app"><h2><span class="step">1</span>Delete in the app</h2><ol><li>Sign in to Little Days.</li><li>Open your <strong>Baby’s profile</strong> from General by tapping the baby photo or name.</li><li>Find <strong>Privacy &amp; support → Delete app account and data</strong>.</li><li>Read the family warning, type <strong>DELETE</strong>, and confirm.</li></ol><p>You do not need to reinstall the app to request deletion: use the email option below if you cannot sign in.</p></section><section id="email"><div class="card"><h2><span class="step">2</span>Request deletion by email</h2><p>Send a request to <a href="mailto:appmakernguyen@gmail.com?subject=Little%20Days%20account%20deletion">appmakernguyen@gmail.com</a>, preferably from the email used for your Little Days account. Include that account email and say you want your Little Days account and associated data deleted.</p><form id="deletion-email" data-lang="en"><label for="account-email">Little Days account email</label><input id="account-email" type="email" name="account-email" autocomplete="email" required placeholder="Your account email"><button class="btn" type="submit">Open email app to request deletion <span aria-hidden="true">↗</span></button><p class="small" style="margin-top:14px">This prepares an email on your device. You must send it to submit your request. Nothing is submitted or deleted by filling this form.</p><p class="status" id="email-status" role="status" aria-live="polite"></p></form><p class="small">If no email app opens, send an email manually with subject <strong>Little Days account deletion</strong>. Do not send your password, verification codes, baby photos or identification documents.</p></div></section><section id="impact"><h2>What is deleted?</h2><p>Your app sign-in account and associated active app records: community profile, posts, photos and videos, comments, likes, app support records, notification/device records, plan/reward records and related reports or blocks.</p><div class="note warn"><p><strong>Family owner:</strong> your shared family’s baby profile, journal, memberships and invitations are also deleted for all members. Other members’ separate sign-in accounts remain. Save anything you need first.</p></div><p><strong>Invited member:</strong> your membership and journal entries you authored are deleted; the rest of the family’s records remain.</p><p>Copies saved by others, provider security/operational logs, independent Google payment/advertising records and any provider recovery copies are not remotely erased by this action. See the <a href="/little-days/privacy/#retention">retention explanation</a>. Uninstalling the app is not account deletion. Account deletion does not cancel a store subscription.</p></section><section id="process"><h2>What happens after an email request?</h2><p>Requests go to our support mailbox and are handled manually. We verify ownership before removing account data; a request does not delete another person’s account just because their email is entered. We aim to respond within 30 days and will tell you if further verification or applicable legal requirements mean more time is needed.</p><p>You can also ask to remove particular content or correct information without deleting your whole account. Describe what you want removed in your email. You may request removal of the correspondence when it is no longer needed.</p><p><a href="/little-days/support/">Need help with deletion?</a></p></section>'''
 return '''<section id="in-app"><h2><span class="step">1</span>Xóa trong ứng dụng</h2><ol><li>Đăng nhập Little Days.</li><li>Tại General (Tổng quan), chạm ảnh hoặc tên bé để mở <strong>Baby’s profile (Hồ sơ bé)</strong>.</li><li>Tìm <strong>Privacy &amp; support → Delete app account and data</strong> (Quyền riêng tư và hỗ trợ → Xóa tài khoản và dữ liệu).</li><li>Đọc cảnh báo về gia đình, nhập <strong>DELETE</strong> và xác nhận.</li></ol><p>Không cần cài lại ứng dụng để yêu cầu xóa. Nếu không đăng nhập được, hãy dùng email bên dưới.</p></section><section id="email"><div class="card"><h2><span class="step">2</span>Yêu cầu xóa qua email</h2><p>Gửi yêu cầu đến <a href="mailto:appmakernguyen@gmail.com?subject=Little%20Days%20account%20deletion">appmakernguyen@gmail.com</a>, tốt nhất từ địa chỉ email của tài khoản Little Days. Ghi email tài khoản và yêu cầu xóa tài khoản Little Days cùng dữ liệu liên quan.</p><form id="deletion-email" data-lang="vi"><label for="account-email">Email tài khoản Little Days</label><input id="account-email" type="email" name="account-email" autocomplete="email" required placeholder="Email tài khoản của bạn"><button class="btn" type="submit">Mở ứng dụng email để yêu cầu xóa <span aria-hidden="true">↗</span></button><p class="small" style="margin-top:14px">Thao tác này soạn email trên thiết bị. Bạn cần gửi thư để gửi yêu cầu. Chỉ điền biểu mẫu không gửi thông tin hay xóa tài khoản.</p><p class="status" id="email-status" role="status" aria-live="polite"></p></form><p class="small">Nếu không mở được ứng dụng email, hãy tự gửi thư với tiêu đề <strong>Little Days account deletion</strong>. Không gửi mật khẩu, mã xác minh, ảnh của bé hoặc giấy tờ tùy thân.</p></div></section><section id="impact"><h2>Dữ liệu nào bị xóa?</h2><p>Tài khoản đăng nhập và dữ liệu ứng dụng đang hoạt động liên quan: hồ sơ cộng đồng, bài viết, ảnh, video, bình luận, lượt thích, tin hỗ trợ trong ứng dụng, dữ liệu thông báo/thiết bị, gói và thưởng, báo cáo hoặc chặn liên quan.</p><div class="note warn"><p><strong>Chủ gia đình:</strong> hồ sơ bé, nhật ký, thành viên và lời mời của gia đình dùng chung cũng bị xóa cho mọi người. Tài khoản đăng nhập riêng của thành viên khác vẫn giữ. Hãy lưu thông tin cần thiết trước.</p></div><p><strong>Thành viên được mời:</strong> tư cách thành viên và nhật ký do bạn tạo bị xóa; dữ liệu khác của gia đình vẫn giữ.</p><p>Thao tác không xóa từ xa bản sao người khác đã lưu, nhật ký vận hành/bảo mật của nhà cung cấp, hồ sơ thanh toán/quảng cáo độc lập của Google hoặc bản khôi phục của nhà cung cấp. Xem <a href="/little-days/vi/privacy/#retention">giải thích về lưu giữ</a>. Gỡ ứng dụng không phải xóa tài khoản. Xóa tài khoản không hủy đăng ký trên cửa hàng.</p></section><section id="process"><h2>Sau khi gửi email</h2><p>Yêu cầu được gửi đến hộp thư hỗ trợ và xử lý thủ công. Chúng tôi xác minh quyền sở hữu trước khi xóa; chỉ nhập email của người khác không thể xóa tài khoản của họ. Chúng tôi đặt mục tiêu phản hồi trong 30 ngày và sẽ thông báo nếu cần thêm thời gian để xác minh hoặc đáp ứng yêu cầu pháp luật.</p><p>Bạn cũng có thể yêu cầu xóa nội dung cụ thể hoặc sửa thông tin mà không xóa toàn bộ tài khoản. Hãy mô tả rõ trong email. Bạn có thể yêu cầu xóa thư trao đổi khi không còn cần thiết.</p><p><a href="/little-days/vi/support/">Cần hỗ trợ việc xóa?</a></p></section>'''

for lang in ['en','vi']:
 vi=lang=='vi';base=P+('/vi/' if vi else '/')
 labels=nav_vi if vi else nav_en
 hero_title='A little clarity.<br>A lot of care.' if not vi else 'Thông tin rõ ràng.<br>An tâm chăm sóc bé.'
 lead='Privacy, account deletion and a real way to reach us. Everything you need to manage your Little Days information.' if not vi else 'Quyền riêng tư, xóa tài khoản và cách liên hệ. Thông tin cần thiết để quản lý dữ liệu Little Days của bạn.'
 cards=[('privacy/','Your information, explained.','What we collect, why we use it, and who can see it.'),('account-deletion/','Your account.<br>Your choice.','Delete in the app, or request deletion without signing in.'),('support/','A little help is here.','Questions, account problems or a concern about community content.')]
 if vi:cards=[('privacy/','Hiểu rõ dữ liệu của bạn.','Thông tin được thu thập, mục đích sử dụng và người có thể xem.'),('account-deletion/','Tài khoản của bạn.<br>Bạn quyết định.','Xóa trong ứng dụng hoặc yêu cầu xóa mà không cần đăng nhập.'),('support/','Luôn có cách liên hệ.','Câu hỏi, vấn đề tài khoản hoặc nội dung cộng đồng cần hỗ trợ.')]
 hub='<div class="hub">'+''.join(f'<a href="{base+k}"><span class="number">0{i+1}</span><h2>{t}</h2><p>{d}</p><span class="arrow" aria-hidden="true">↗</span></a>' for i,(k,t,d) in enumerate(cards))+'</div>'
 hub+='<div class="sectionline"></div><p class="small">'+('This is the public help website for <strong>Little Days</strong>. No app account is needed to read these pages. The app is for adult parents and caregivers; it is not a medical advice or emergency service.' if not vi else 'Đây là trang hỗ trợ công khai của <strong>Little Days</strong>. Không cần tài khoản ứng dụng để đọc. Ứng dụng dành cho cha mẹ và người chăm sóc trưởng thành, không phải dịch vụ tư vấn y tế hay cấp cứu.')+'</p>'
